package org.hiero.mirror.common.domain.clpr;

/**
 * Mirrors the real {@code ClprMaintenanceReason} proto enum. {@code CLPR_MAINTENANCE_REASON_UNSPECIFIED} is reserved
 * and never generated by a node, but is included so an unexpected occurrence can be recorded rather than dropped.
 */
public enum ClprMaintenanceReason {
    CLPR_MAINTENANCE_REASON_UNSPECIFIED,
    GENESIS_INITIALIZATION,
    UPGRADE_INITIALIZATION,
    UPGRADE_ROSTER_RECONCILIATION,
    ENDPOINT_MANIFEST_RECONCILIATION
}
